from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Forward substitution for lower-triangular system L * x = b.
# We accumulate into a scalar xi to keep x[i] in a register and then
# apply a small unrolling on the inner loop to improve ILP.
@proc
def kernel_trisolv(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Local accumulator for the i-th row/entry of x
        xi: DATA_TYPE
        xi = b[i]
        for j in seq(0, i):
            # Same arithmetic as: xi = xi - L[i, j] * x[j]
            xi = xi - L[i, j] * x[j]
        xi = xi / L[i, i]
        x[i] = xi


# ------------------------
# Scheduling / Optimization
# ------------------------

# Unroll factor for the inner j loop. This is a compile-time constant
# that can be tuned for the target CPU.
UNROLL_J = 4

_kernel_trisolv_scheduled = kernel_trisolv

# Split the inner j-loop into (jo, ji) with a constant inner extent UNROLL_J.
# This keeps the original triangular iteration space but exposes a
# fixed-size inner loop for unrolling:
#   for j in 0..i:
#     ...
# becomes roughly
#   for jo in 0..i/UNROLL_J:
#     for ji in 0..UNROLL_J:
#       j = UNROLL_J*jo + ji
#   for ji in 0..(i - UNROLL_J*(i/UNROLL_J)):
#       j = UNROLL_J*(i/UNROLL_J) + ji
j_loop = _kernel_trisolv_scheduled.find_loop("j")
_kernel_trisolv_scheduled = divide_loop(
    _kernel_trisolv_scheduled,
    j_loop,
    UNROLL_J,
    ("jo", "ji"),
    tail="cut",
)

# Unroll the fixed-size inner ji loop (extent = UNROLL_J).
# This reduces loop overhead and lets the backend keep multiple
# independent multiply-adds in flight.
ji_loop = _kernel_trisolv_scheduled.find_loop("ji")
_kernel_trisolv_scheduled = unroll_loop(_kernel_trisolv_scheduled, ji_loop)

# Perform algebraic and control-flow simplifications on the result.
_kernel_trisolv_scheduled = simplify(_kernel_trisolv_scheduled)

# Export the optimized kernel under the original name expected by the C driver.
kernel_trisolv = rename(_kernel_trisolv_scheduled, "kernel_trisolv")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_trisolv (/*ctxt=*/NULL,
                  n,
                  (DATA_TYPE*)POLYBENCH_ARRAY(L),
                  (DATA_TYPE*)POLYBENCH_ARRAY(x),
                  (DATA_TYPE*)POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
