from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline forward-substitution kernel: solve L x = b for x,
# where L is a lower-triangular n x n matrix stored in row-major order.
@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Compute the dot product of the strictly lower-triangular
        # part of row i of L with the already computed part of x.
        sum_val: DATA_TYPE
        sum_val = 0.0
        for j in seq(0, i):
            sum_val += L[i, j] * x[j]

