# original PolyBench kernel but accumulate into a scalar temporary to
# reduce memory traffic on x[i].
@proc
def kernel_trisolv_base(
    n: size,
    L: DATA_TYPE[n, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    b: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Local accumulator for the current solution entry x[i].
        # This keeps the running partial sum in a scalar instead of
        # repeatedly writing x[i] back to memory.
        xi: DATA_TYPE
        xi = b[i]

        # For a given row i, we subtract the known contributions
        # from previously computed x[0..i-1].
        for j in seq(0, i):
            xi = xi - L[i, j] * x[j]

        # Final division by the diagonal element.
        x[i] = xi / L[i, i]


